import { PulsingBorder, type PulsingBorderProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#52527a", "#8a8a95", "#3a3a5c"];

interface ShaderPulsingBorderProps
  extends Omit<PulsingBorderProps, "frame" | "ref"> {}

function ShaderPulsingBorderBase({
  speed = 1,
  colorBack = "#12121a",
  colors = NEUTRAL_COLORS,
  roundness = 0.25,
  thickness = 0.1,
  intensity = 0.2,
  bloom = 0.25,
  className,
  ...rest
}: ShaderPulsingBorderProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-pulsing-border"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <PulsingBorder
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colors={colors}
        roundness={roundness}
        thickness={thickness}
        intensity={intensity}
        bloom={bloom}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  thickness: {
    type: "number",
    min: 0.02,
    max: 0.5,
    step: 0.02,
    default: 0.1,
    description: "Thickness",
    hiddenFromList: false,
  },
  roundness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.25,
    description: "Roundness",
    hiddenFromList: false,
  },
  intensity: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.2,
    description: "Intensity",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","thickness","roundness","intensity","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  thickness: 0.1,
  roundness: 0.25,
  intensity: 0.2,
  colorBack: "#12121a",
};

type ShaderPulsingBorderElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderPulsingBorderBase>;

const ShaderPulsingBorderInner = forwardRef<
  HTMLDivElement,
  ShaderPulsingBorderElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderPulsingBorder>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderPulsingBorderBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderPulsingBorderBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderPulsingBorder = Interactive.withSchema({
  Component: ShaderPulsingBorderInner,
  componentName: "<ShaderPulsingBorder>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
